template<>struct Wire<SR_REQUEST> {static Json Encode(const SR_REQUEST& v){Json j=Json::object();j["Version"]=EncodeWire(v.Version);j["Size"]=EncodeWire(v.Size);j["DeviceId"]=EncodeWire(v.DeviceId);return j;}static void Decode(const Json& j,SR_REQUEST& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Version")DecodeWire(it.value(),v.Version);else if(it.key()=="Size")DecodeWire(it.value(),v.Size);else if(it.key()=="DeviceId")DecodeWire(it.value(),v.DeviceId);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
